public class RecordListStoreProbe {
    public static List<SObject> contactRows() {
        return new List<SObject>{new Contact(LastName='Synthetic contact')};
    }
    public static List<SObject> accountRows() {
        return new List<SObject>{new Account(Name='Synthetic account')};
    }
    public static Map<String,Object> observe(Boolean matching) {
        Map<String,Object> result=new Map<String,Object>{'matching'=>matching};
        String phase='factory';
        try {
            List<SObject> source=matching ? accountRows() : contactRows();
            result.put('sourceSize',source.size());
            result.put('sourceType',String.valueOf(source[0].getSObjectType()));
            phase='assignment';
            List<Account> rows=source;
            result.put('assignedSize',rows.size());
            phase='cast';
            List<Account> additional=(List<Account>)(matching ? accountRows() : contactRows());
            result.put('castSize',additional.size());
            phase='addAll';
            rows.addAll(additional);
            result.put('finalSize',rows.size());
            phase='complete';
        } catch(Exception failure) {
            result.put('exceptionType',failure.getTypeName());
            result.put('exceptionMessage',failure.getMessage());
        }
        result.put('phase',phase);
        return result;
    }
    public static Map<String,Object> run() {
        return new Map<String,Object>{'foreign'=>observe(false),'matching'=>observe(true)};
    }
}

