public class RecordListTypedGuardProbe {
 public static Map<String,Object> observe(Boolean useMany) {
  List<Account> backing=new List<Account>{new Account(Name='Synthetic account')};
  List<SObject> view=backing;
  Map<String,Object> result=new Map<String,Object>{'useMany'=>useMany,'beforeSize'=>view.size()};
  try {
   if(useMany) {view.addAll(new List<SObject>{new Contact(LastName='Synthetic contact')});}
   else {view.add(new Contact(LastName='Synthetic contact'));}
   result.put('phase','complete');
  } catch(Exception ex) {
   result.put('phase',useMany?'addAll':'add');
   result.put('exceptionType',ex.getTypeName());
   result.put('exceptionMessage',ex.getMessage());
  }
  result.put('afterSize',view.size());
  return result;
 }
 public static Map<String,Object> run(){return new Map<String,Object>{'add'=>observe(false),'addAll'=>observe(true)};}
}

